<?php
require_once __DIR__.'/../includes/database.php';require_once __DIR__.'/../includes/stock-transfer.php';
function team_transfer_check($ok,$why){if(!$ok)throw new RuntimeException($why);}function team_transfer_denied($fn){try{$fn();}catch(CatalogException $e){team_transfer_check($e->status===403,$e->getMessage());return;}throw new RuntimeException('Expected 403');}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);initialize_database($db);foreach(['Admin','Operator','Owner'] as $i=>$n)stock_query($db,'INSERT INTO users(name,public_name,email,password_hash) VALUES(?,?,?,?)',[$n,$n,'user'.$i.'@example.invalid','unused']);stock_query($db,"INSERT INTO stock_branches(owner_id,name,address,locality,province) VALUES(1,'Branch','A','B','C')");stock_query($db,"INSERT INTO branch_workspaces(owner_id,name) VALUES(1,'Team')");stock_query($db,'INSERT INTO branch_workspace_locations(branch_id,workspace_id) VALUES(1,1)');stock_query($db,"INSERT INTO branch_team_members(branch_id,user_id,role) VALUES(1,2,'operator')");
function team_transfer_pallet($db,$user,$branch){$label=stock_generate($db,$user);$p=stock_claim($db,$label['code'],$user);stock_query($db,'UPDATE pallets SET branch_id=? WHERE id=?',[$branch,$p['id']]);return $p;}
$a=team_transfer_pallet($db,3,1);$b=team_transfer_pallet($db,3,1);$outside=team_transfer_pallet($db,2,null);stock_query($db,'UPDATE pallets SET description=? WHERE id=?',['Keep source',$a['id']]);stock_query($db,'UPDATE pallets SET description=? WHERE id=?',['Keep target',$b['id']]);stock_save_product($db,3,['pallet_id'=>$a['id'],'ean'=>'96385074','amount'=>2,'kind'=>'boxes','pack_size'=>12,'expires'=>'2030-01-01']);stock_save_product($db,3,['pallet_id'=>$b['id'],'ean'=>'96385074','amount'=>5,'expires'=>'2030-01-01']);
$d=stock_detail($db,$a['code'],2);team_transfer_check($d['team_access']&&!$d['can_edit_description']&&$d['can_transfer_stock'],'team flags');team_transfer_denied(fn()=>stock_transfer_preview($db,2,['pallet_id'=>$a['id'],'mode'=>'user','email'=>'user0@example.invalid']));team_transfer_denied(fn()=>stock_transfer_preview($db,2,['pallet_id'=>$a['id'],'mode'=>'pallet','target_code'=>$outside['code']]));
$input=['pallet_id'=>$a['id'],'mode'=>'pallet','target_code'=>$b['code']];$preview=stock_transfer_preview($db,2,$input);$db->beginTransaction();stock_transfer_commit($db,2,array_map('strval',$input+$preview));$db->commit();team_transfer_check((int)stock_query($db,'SELECT SUM(units) FROM pallet_products WHERE pallet_id=?',[$b['id']])->fetchColumn()===29,'exact sum');team_transfer_check(stock_query($db,'SELECT description FROM pallets WHERE id=?',[$a['id']])->fetchColumn()==='Keep source','source description untouched');team_transfer_check(stock_query($db,'SELECT description FROM pallets WHERE id=?',[$b['id']])->fetchColumn()==='Keep target','target description untouched');
$label=stock_generate($db,2);$input=['pallet_id'=>$b['id'],'mode'=>'pallet','target_code'=>$label['code']];$preview=stock_transfer_preview($db,2,$input);$db->beginTransaction();$moved=stock_transfer_commit($db,2,array_map('strval',$input+$preview));$db->commit();$target=stock_query($db,'SELECT owner_id,branch_id FROM pallets WHERE id=?',[$moved['target_id']])->fetch();team_transfer_check((int)$target['owner_id']===3&&(int)$target['branch_id']===1,'new QR preserves owner and branch');stock_query($db,'UPDATE branch_team_members SET expires_at=? WHERE user_id=2',[time()-1]);team_transfer_denied(fn()=>stock_transfer_preview($db,2,['pallet_id'=>$moved['target_id'],'mode'=>'pallet','target_code'=>$a['code']]));echo "OK: team-only stock transfer, no user/cross-branch transfer, sums/dates, immutable descriptions, new QR ownership and expiry.\n";
